// quizData.js  —  Rebrain  (he | ar)
// Weekly content renewal + daily difficulty progression
//
// ARCHITECTURE:
//   • 5 themed weekly packs (rotate every week, cycling through all 5)
//   • Each pack has word recall, trivia, and pattern banks by difficulty level 1–10
//   • getDifficultyLevel(dateStr) → 1-10 (3-day blocks, 30-day full cycle)
//   • getWeekPack(dateStr)        → one of 5 themed packs
//   • getDailyGames(dateStr)      → [wordRecall, trivia, pattern] for that day

export const GAME_TYPES = {
  WORD_RECALL: "word_recall",
  TRIVIA:      "trivia",
  PATTERN:     "pattern",
};

const LAUNCH = new Date("2026-06-27");

export function getDifficultyLevel(dateStr) {
  const dayNum = Math.max(0, Math.floor((new Date(dateStr) - LAUNCH) / 86400000));
  const pos = dayNum % 30;
  if (pos < 3)  return 1;
  if (pos < 6)  return 2;
  if (pos < 9)  return 3;
  if (pos < 12) return 4;
  if (pos < 15) return 5;
  if (pos < 18) return 6;
  if (pos < 21) return 7;
  if (pos < 24) return 8;
  if (pos < 27) return 9;
  return 10;
}

export function getWeekNumber(dateStr) {
  return Math.floor(Math.max(0, Math.floor((new Date(dateStr) - LAUNCH) / 86400000)) / 7);
}
export function getWeekPack(dateStr) {
  return getWeekNumber(dateStr) % 5;
}

