export const wordRecallRounds = weeklyPacks[0].wordRecall[1].concat(weeklyPacks[0].wordRecall[2]);
export const triviaQuestions  = weeklyPacks[0].trivia[1].concat(weeklyPacks[0].trivia[2]);
export const patternSequences = weeklyPacks[0].pattern[1].concat(weeklyPacks[0].pattern[2]);